/**
 * Definition for a binary tree node.
 * class TreeNode {
 *     val: number
 *     left: TreeNode | null
 *     right: TreeNode | null
 * }
 */
// 遞迴：交換左右子樹，再分別翻轉
// 時間複雜度: O(n)，空間複雜度: O(h)
function invertTree(root) {
    if (!root)
        return null;
    [root.left, root.right] = [invertTree(root.right), invertTree(root.left)];
    return root;
}

